<template>
  <section class="privacy-desk"><header class="desk-intro"><span>个人信息权利申请</span><h2>核对申请，给出明确回复。</h2><p>仅在处理必要范围内查看资料。不索取账号密码或无关证件；工单办结表示已回复，实际删除与注销需核对并执行。</p></header><p v-if="error" class="desk-message" role="alert">{{ error }}<button type="button" @click="load">重新读取</button></p><p v-if="notice" class="desk-message done" role="status">{{ notice }}</p>
    <div class="desk-grid"><section class="desk-list"><p v-if="loading" class="empty" role="status">正在读取权利申请…</p><p v-else-if="!rows.length" class="empty">暂无个人信息权利申请。</p><button v-for="row in rows" :key="row.id" class="case" :class="{ selected: selected?.id === row.id }" type="button" @click="open(row)"><span>{{ statuses[row.status] || row.status }} · #{{ row.id }}</span><h3>{{ types[row.type] || row.type }}</h3><p>{{ row.nickname || row.userNickname || '用户 #' + row.userId }}</p><small>{{ String(row.createdAt || '').slice(0, 10) }}</small></button><div v-if="pages > 1" class="pagination"><button :disabled="loading || saving || page <= 1" type="button" @click="turn(-1)">上一页</button><span>{{ page }}/{{ pages }} · {{ total }} 条</span><button :disabled="loading || saving || page >= pages" type="button" @click="turn(1)">下一页</button></div></section>
      <section v-if="selected" class="case-detail"><header><span>私密申请 · 仅平台管理员</span><h2>{{ types[selected.type] || selected.type }}</h2><p>工单 #{{ selected.id }} · {{ selected.nickname || selected.userNickname || '用户 #' + selected.userId }}</p></header><div class="private-content">{{ selected.detail }}</div><div v-if="selected.response" class="previous"><b>最近回复</b><p>{{ selected.response }}</p></div><form @submit.prevent="save"><label>处理状态<select v-model="status" aria-label="处理状态" :disabled="saving"><option value="processing">处理中</option><option value="needs_info">需要本人补充</option><option value="completed">已回复办结</option><option value="rejected">未予办理并说明理由</option></select></label><label>向申请人的回复<textarea v-model="response" aria-label="向申请人的回复" maxlength="2000" rows="6" required :disabled="saving" placeholder="说明核验情况、已采取的实际动作、未能办理的依据、保存范围与后续途径。勿包含其他用户资料。" /></label><p class="save-note">选择“已回复办结”仅更新工单状态，不会自动删除业务数据或账号。请在实际操作完成后准确说明结果。</p><button class="save" type="submit" :disabled="saving">{{ saving ? '正在保存…' : '记录处理结果' }}</button></form></section><section v-else class="case-detail empty">选择一条申请，核对必要信息后再处理。</section>
    </div>
  </section>
</template>
<script setup>
import { onBeforeUnmount, ref, watch } from 'vue';
const props = defineProps({ request: { type: Function, required: true }, sessionToken: String, refreshKey: Number });
const types = { access: '查阅个人信息', copy: '复制个人信息', correct: '更正或补充', delete: '删除个人信息', withdraw: '撤回同意', close: '注销账号', other: '其他权利或投诉' }, statuses = { pending: '已提交', processing: '处理中', needs_info: '待本人补充', completed: '已回复办结', rejected: '未予办理' };
const rows = ref([]), selected = ref(null), page = ref(1), pages = ref(1), total = ref(0), status = ref('processing'), response = ref(''), loading = ref(false), saving = ref(false), error = ref(''), notice = ref('');
let version = 0, disposed = false;
function clear() { version++; rows.value = []; selected.value = null; response.value = ''; loading.value = false; saving.value = false; error.value = ''; notice.value = ''; }
function stamp() { return { version, token: props.sessionToken }; }
function current(state) { if (props.sessionToken !== sessionStorage.getItem('marathon_admin')) { clear(); return false; } return !disposed && state.version === version && state.token === props.sessionToken; }
async function load() { const state = { ...stamp(), version: ++version }; loading.value = true; error.value = ''; try { const data = await props.request('/admin/privacy-requests?page=' + page.value); if (!current(state)) return; rows.value = data.rows || []; total.value = data.total || 0; pages.value = data.pages || 1; page.value = data.page || 1; if (selected.value) selected.value = rows.value.find(row => row.id === selected.value.id) || null; } catch (err) { if (current(state)) { if ([401, 403].includes(err.status)) { rows.value = []; selected.value = null; response.value = ''; } error.value = err.message; } } finally { if (current(state)) loading.value = false; } }
function open(row) { if (saving.value) return; selected.value = row; response.value = ''; status.value = 'processing'; notice.value = ''; }
function turn(delta) { if (saving.value) return; selected.value = null; page.value += delta; load(); }
async function save() { if (!selected.value || saving.value) return; const state = stamp(); if (!current(state)) return; const text = response.value.trim(); if (!text) { error.value = '请向申请人说明实际处理结果与后续途径。'; return; } const id = selected.value.id; saving.value = true; error.value = ''; notice.value = ''; try { await props.request('/admin/privacy-requests/' + id + '/decision', { method: 'POST', body: JSON.stringify({ status: status.value, response: text }) }); if (!current(state)) return; response.value = ''; saving.value = false; notice.value = '处理回复已记录，申请人可在个人信息权利页面查看。'; await load(); } catch (err) { if (current(state)) error.value = err.message; } finally { if (current(state)) saving.value = false; } }
function sessionChanged() { if (props.sessionToken !== sessionStorage.getItem('marathon_admin')) clear(); }
window.addEventListener('storage', sessionChanged); window.addEventListener('focus', sessionChanged);
watch(() => props.refreshKey, () => { if (!saving.value) load(); }); watch(() => props.sessionToken, () => { clear(); if (props.sessionToken) load(); }); onBeforeUnmount(() => { disposed = true; clear(); window.removeEventListener('storage', sessionChanged); window.removeEventListener('focus', sessionChanged); }); load();
</script>
<style scoped>
.privacy-desk{color: var(--ink);min-width:0}.privacy-desk *{box-sizing:border-box}.desk-intro {padding:25px;background: var(--card);border:1px solid var(--line);border-radius: 18px;}.desk-intro>span{font-size:12px;color:var(--muted);letter-spacing:0}.desk-intro h2{font-size:23px;margin:15px 0;line-height:1.5}.desk-intro p{font-size:12px;color:var(--muted);line-height:1.95;margin:0}.desk-grid{display:grid;grid-template-columns:minmax(230px,.75fr) minmax(0,1.5fr);gap:20px;margin-top:22px;align-items:start}.desk-list {background:white;border:1px solid var(--line);border-radius: 18px;overflow:hidden}.case{width:100%;display:block;text-align:left;padding:20px;background:#fff;border-bottom:1px solid var(--line);min-height:44px;overflow-wrap:anywhere}.case.selected{background:var(--accent-soft);box-shadow:inset 3px 0 var(--accent)}.case>span{font-size: 12px;color:var(--muted)}.case h3{font-size:16px;margin:12px 0}.case p{font-size: 12px;color:var(--muted);line-height:1.8;margin:7px 0}.case small{font-size: 12px;color:var(--muted)}.case-detail {border:1px solid var(--line);border-radius: 18px;background:white;padding:26px;min-width:0;overflow-wrap:anywhere}.case-detail header>span{font-size: 12px;color:var(--muted)}.case-detail header h2{font-size:23px;margin:15px 0;line-height:1.6}.case-detail header p{font-size:12px;color:var(--muted);line-height:1.8}.private-content{padding:18px;border-radius:11px;background:var(--field-bg);font-size:12px;line-height:2;color: var(--muted);white-space:pre-wrap;margin:22px 0}.previous{background:#fcf7f9;padding:17px;border-radius:10px;font-size:12px;color:var(--muted);line-height:1.9}.previous>b{font-weight:500;font-size: 12px}.previous p{white-space:pre-wrap;margin:10px 0 0}.case-detail form{border-top:1px solid var(--line);padding-top:7px;margin-top:25px}.case-detail label {display:grid;gap:12px;margin:20px 0;font-size: 13px;color:var(--muted);line-height:1.8}.case-detail select,.case-detail textarea {font:inherit;border:1px solid var(--line);background: var(--field-bg);border-radius: 12px;min-width:0;width:100%;padding:12px;line-height:1.9;min-height:46px;color: var(--ink-secondary);}.save-note {font-size: 12px;color: var(--muted);background: var(--field-bg);line-height:1.95;padding:15px;border-radius: 12px;}.save{background:var(--accent);color:#fff;min-height:45px;border-radius:12px;padding:12px 22px;font-weight:600;font-size:12px}.desk-message{font-size:12px;color:var(--accent);background:var(--accent-soft);border-radius:9px;padding:15px 18px;line-height:1.9}.desk-message button{color:var(--accent);min-height:44px;margin-left:12px;font-size: 12px}.desk-message.done{color:#527e68;background:#eef8f2}.empty{padding:40px 22px;text-align:center;color:var(--muted);font-size:12px;line-height:1.9}.pagination{display:flex;align-items:center;justify-content:center;gap:12px;padding:12px;font-size: 12px;color:var(--muted)}.pagination button{color:var(--muted);min-height:44px;font-size: 12px}.privacy-desk button:disabled{opacity:.5}.privacy-desk button:focus-visible,.privacy-desk select:focus-visible,.privacy-desk textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:850px){.desk-grid{grid-template-columns:minmax(0,1fr)}.desk-intro {padding:21px; background: var(--card); border-radius: 18px;}.desk-intro h2{font-size:21px}.case-detail {padding:21px; border-radius: 18px;}}
</style>
